import { prisma } from "@/lib/prisma";import { mobileApiError,mobileJson,mobileOptions,requireMobileUser } from "@/lib/mobile-api";import { requireRoomPermission } from "@/lib/audio-room-management";import { emitToAudioRoom } from "@/lib/realtime";
export function OPTIONS(){return mobileOptions()}
async function ctx(request,params){const actor=await requireMobileUser(request);const {roomId,publicId}=await params;const room=await prisma.audioRoom.findUnique({where:{roomId:decodeURIComponent(roomId)},select:{id:true,roomId:true,ownerId:true}});if(!room)throw new Error("ROOM_UNAVAILABLE");await requireRoomPermission(room,actor.id,"canModerateMembers");const target=await prisma.user.findUnique({where:{publicId:decodeURIComponent(publicId)},select:{id:true,publicId:true}});if(!target)throw new Error("USER_NOT_FOUND");if(target.id===room.ownerId)throw Object.assign(new Error("The room owner cannot be blacklisted."),{code:"VALIDATION_ERROR"});return{actor,room,target}}
export async function PUT(request,{params}){try{const {actor,room,target}=await ctx(request,params),body=await request.json(),duration=Number(body.durationMinutes??0);if(!Number.isSafeInteger(duration)||duration<0||duration>525600)throw Object.assign(new Error("durationMinutes must be 0 to 525600."),{code:"VALIDATION_ERROR"});const reason=String(body.reason??"").trim().slice(0,300)||null,expiresAt=duration===0?null:new Date(Date.now()+duration*60000),banId=`RBAN-${crypto.randomUUID()}`;const updated=await prisma.$transaction(async tx=>{await tx.audioRoomBan.updateMany({where:{audioRoomId:room.id,userId:target.id,revokedAt:null},data:{revokedAt:new Date()}});await tx.audioRoomBan.create({data:{publicId:banId,audioRoomId:room.id,userId:target.id,actorId:actor.id,reason,expiresAt}});await tx.audioRoomMember.updateMany({where:{audioRoomId:room.id,userId:target.id},data:{socketCount:0,lastSeenAt:new Date()}});await tx.audioRoomSeat.updateMany({where:{audioRoomId:room.id,occupantUserId:target.id},data:{occupantUserId:null,occupiedAt:null,isMuted:true,isSpeaking:false}});await tx.audioRoomModerationLog.create({data:{id:`MOD-${crypto.randomUUID()}`,audioRoomId:room.id,actorId:actor.id,targetId:target.id,action:"ROOM_BANNED",reason,durationMinutes:duration,expiresAt}});return tx.audioRoom.update({where:{id:room.id},data:{revision:{increment:1}},select:{revision:true}})});const data={roomId:room.roomId,userId:target.publicId,reason,expiresAt:expiresAt?.toISOString()??null,revision:updated.revision};emitToAudioRoom(room.roomId,"audio-room:member-banned",{success:true,data});globalThis.portalRemoveFromAudioRoom?.(target.publicId,room.roomId,{code:"ROOM_BANNED",message:"You were removed from this room."});return mobileJson({success:true,data})}catch(e){return mobileApiError(e,"ROOM_BLACKLIST_UPDATE_FAILED")}}
export async function DELETE(request,{params}){try{const {actor,room,target}=await ctx(request,params);const updated=await prisma.$transaction(async tx=>{await tx.audioRoomBan.updateMany({where:{audioRoomId:room.id,userId:target.id,revokedAt:null},data:{revokedAt:new Date()}});await tx.audioRoomModerationLog.create({data:{id:`MOD-${crypto.randomUUID()}`,audioRoomId:room.id,actorId:actor.id,targetId:target.id,action:"ROOM_UNBANNED"}});return tx.audioRoom.update({where:{id:room.id},data:{revision:{increment:1}},select:{revision:true}})});return mobileJson({success:true,data:{roomId:room.roomId,userId:target.publicId,revision:updated.revision}})}catch(e){return mobileApiError(e,"ROOM_BLACKLIST_DELETE_FAILED")}}
